/* ===== Estado da sacola ===== */
const MAX_QTY = 99;                       // teto por item na sacola
const isProduct = id => Object.prototype.hasOwnProperty.call(ALL, id);
let cart = {};
try {
  const raw = JSON.parse(localStorage.getItem("mina-cart") || "{}");
  if (raw && typeof raw === "object" && !Array.isArray(raw)) {
    for (const k of Object.keys(raw)) {
      const q = Math.floor(Number(raw[k]));
      if (isProduct(k) && Number.isFinite(q) && q > 0) cart[k] = Math.min(q, MAX_QTY);
    }
  }
} catch(e){ cart = {}; }
const save = () => { try { localStorage.setItem("mina-cart", JSON.stringify(cart)); } catch(e){} };

/* ===== Horário de funcionamento ===== */
const HOURS = {0:null, 1:["05:00","19:30"], 2:["06:00","19:30"], 3:["06:00","19:30"], 4:["06:00","19:30"], 5:["06:00","19:30"], 6:["06:00","19:30"]};
const p2 = n => String(n).padStart(2,"0");
const fmtH = t => { const [h,m] = t.split(":"); return `${Number(h)}h${m!=="00" ? m : ""}`; };
const DAYN = ["domingo","segunda","terça","quarta","quinta","sexta","sábado"];
function storeState(){
  const now = new Date(), h = HOURS[now.getDay()], hm = `${p2(now.getHours())}:${p2(now.getMinutes())}`;
  if (h && hm >= h[0] && hm < h[1]) return {open:true, close:h[1]};
  if (h && hm < h[0]) return {open:false, when:"hoje", at:fmtH(h[0])};
  for (let i=1; i<=7; i++) { const d = new Date(now); d.setDate(d.getDate()+i); const x = HOURS[d.getDay()]; if (x) return {open:false, when: i===1 ? "amanhã" : DAYN[d.getDay()], at:fmtH(x[0])}; }
}

/* ===== Fornadas ao vivo ===== */
const BATCHES = [6, 11, 16];
function renderBatches(){
  const now = new Date(), mins = now.getHours()*60 + now.getMinutes(), st = storeState();
  const openToday = !!HOURS[now.getDay()];
  const next = openToday ? BATCHES.find(h => h*60 > mins) : undefined;
  let promo, tag;
  if (!st.open) {
    promo = `Estamos fechados agora · abrimos ${st.when} às <b>${st.at}</b>`;
    tag = `Fechado · abrimos ${st.when} às ${st.at}`;
  } else if (next === undefined) {
    promo = `Aberto até as <b>${fmtH(st.close)}</b> · fornadas de hoje já saíram`;
    tag = `Aberto agora · até ${fmtH(st.close)}`;
  } else {
    const d = next*60 - mins, h = Math.floor(d/60), m = d%60;
    promo = `Próxima fornada às <b>${next}h</b> · em ${h ? h+"h " : ""}${m}min`;
    tag = `Aberto agora · até ${fmtH(st.close)}`;
  }
  $("#promoMsg").innerHTML = promo;
  $("#heroTag").textContent = tag;
  $("#timeline").innerHTML = (openToday ? "" : `<span class="batch"><span class="ic"></span>Domingo fechado <small>fornadas voltam amanhã</small></span>`) + BATCHES.map(h=>{
    const done = openToday && h*60 <= mins, isNext = h === next;
    const label = h===6 ? "Pão francês e croissant" : h===11 ? "Pão francês e salgados" : "Pão francês e pão de queijo";
    return `<span class="batch ${done?"done":""} ${isNext?"next":""}"><span class="ic">${done?"✓":""}</span>${h}h <small>${label}</small></span>`;
  }).join("");
}
renderBatches(); setInterval(renderBatches, 30000);

/* ===== Hero carrossel ===== */
$("#arts").innerHTML = SLIDES.map((s,i)=>`<div class="art${i===0?" on":""}" data-i="${i}">${ART[s.art]}</div>`).join("");
$("#badge1").innerHTML = badgeSVG("ring1", "#FAF2E6", K);
$("#dots").innerHTML = SLIDES.map((s,i)=>`<button aria-label="${ALL[s.id].name}" data-i="${i}" aria-current="${i===0}"><i></i></button>`).join("");
let slide = 0, timer;
function showSlide(i, first){
  slide = (i + SLIDES.length) % SLIDES.length;
  const s = SLIDES[slide], p = ALL[s.id], hero = $("#hero");
  hero.style.setProperty("--bg", s.bg); hero.style.setProperty("--fg", s.fg);
  hero.style.setProperty("--btn-bg", s.btnBg); hero.style.setProperty("--btn-fg", s.btnFg);
  document.querySelectorAll(".art").forEach(a=>a.classList.toggle("on", Number(a.dataset.i)===slide));
  document.querySelectorAll("#dots button").forEach(d=>d.setAttribute("aria-current", String(Number(d.dataset.i)===slide)));
  const fill = () => {
    $("#word").textContent = s.word;
    $("#sNote").textContent = s.note;
    $("#sName").textContent = p.name;
    $("#sDesc").textContent = s.desc;
    $("#sPrice").innerHTML = brl(p.price) + (p.unit ? `<small>${p.unit}</small>` : "");
    $("#sSticker").textContent = s.sticker;
    $("#sAdd").dataset.add = s.id;
  };
  if (first) { fill(); return; }
  const info = $("#slideInfo"); info.classList.add("out"); $("#word").style.opacity = 0;
  setTimeout(()=>{ fill(); info.classList.remove("out"); $("#word").style.opacity = ""; }, 260);
}
function restart(){ clearInterval(timer); timer = setInterval(()=>showSlide(slide+1), 5200); }
showSlide(0, true); restart();
$("#prev").addEventListener("click", ()=>{ showSlide(slide-1); restart(); });
$("#next").addEventListener("click", ()=>{ showSlide(slide+1); restart(); });
